const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry definitions
  // Queensland, Australia - approximate bounding box
  const queensland = ee.Geometry.Rectangle([138.0, -29.0, 153.0, -10.0]);

  // Lut Desert, Iran - approximate center point with buffer
  const lutDesert = ee.Geometry.Point([58.4, 30.0]).buffer(10000); // 10km buffer

  // El Azizia, Libya - approximate location with buffer
  const elAzizia = ee.Geometry.Point([13.0, 32.5]).buffer(10000); // 10km buffer

  // 2. Time period
  const startDate = '2003-01-01';
  const endDate = '2003-12-31';

  // 3. MODIS LST data - MOD11A1.061 product
  const modisCol = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'QC_Day']);

  // Check if collection has data
  const collectionSize = modisCol.size().getInfo();
  console.log(`2003 MODIS Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Process LST data - convert to Celsius and mask poor quality
  const processLST = function(image) {
    // Get LST band and apply scale factor (0.02 for Kelvin)
    const lst = image.select('LST_Day_1km').multiply(0.02);

    // Convert Kelvin to Celsius
    const lstC = lst.subtract(273.15);

    // QC mask: bits 0-1 = 00 (good quality) or 01 (other quality)
    const qc = image.select('QC_Day');
    const qcMask = qc.bitwiseAnd(3).lte(1); // bits 0-1 <= 01

    return lstC.updateMask(qcMask).rename('LST_C');
  };

  const processedCol = modisCol.map(processLST);

  // 5. Create maximum temperature composite for the year
  const maxLST = processedCol.max();

  // 6. Extract maximum temperatures for each region
  const reducer = ee.Reducer.max();

  // Queensland - use 3000m scale due to large area
  const queenslandStats = maxLST.reduceRegion({
    reducer: reducer,
    geometry: queensland,
    scale: 3000,
    maxPixels: 1e9
  });

  const queenslandMax = queenslandStats.get('LST_C').getInfo();
  console.log(`Queensland max LST: ${queenslandMax ? queenslandMax.toFixed(2) : 'null'}°C`);

  // Lut Desert
  const lutStats = maxLST.reduceRegion({
    reducer: reducer,
    geometry: lutDesert,
    scale: 1000,
    maxPixels: 1e9
  });

  const lutMax = lutStats.get('LST_C').getInfo();
  console.log(`Lut Desert max LST: ${lutMax ? lutMax.toFixed(2) : 'null'}°C`);

  // El Azizia
  const aziziaStats = maxLST.reduceRegion({
    reducer: reducer,
    geometry: elAzizia,
    scale: 1000,
    maxPixels: 1e9
  });

  const aziziaMax = aziziaStats.get('LST_C').getInfo();
  console.log(`El Azizia max LST: ${aziziaMax ? aziziaMax.toFixed(2) : 'null'}°C`);

  // 7. Check for invalid data
  if (queenslandMax === null || lutMax === null || aziziaMax === null) {
    // Check if any region has no valid pixels
    const checkValid = function(val, name) {
      return val === null || val === undefined || isNaN(val);
    };

    if (checkValid(queenslandMax, 'Queensland') || 
        checkValid(lutMax, 'Lut Desert') || 
        checkValid(aziziaMax, 'El Azizia')) {
      console.log("<answer>C3</answer>");
      return;
    }
  }

  // 8. Validate temperature ranges (reasonable LST bounds)
  const isValidTemp = function(temp) {
    return temp > -50 && temp < 100; // Reasonable Celsius range
  };

  if (!isValidTemp(queenslandMax) || !isValidTemp(lutMax) || !isValidTemp(aziziaMax)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 9. Compare temperatures
  console.log(`Comparison: Queensland (${queenslandMax.toFixed(2)}°C) vs ` +
              `Lut Desert (${lutMax.toFixed(2)}°C) vs ` +
              `El Azizia (${aziziaMax.toFixed(2)}°C)`);

  if (queenslandMax > lutMax && queenslandMax > aziziaMax) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
